const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
(async()=>{
  const browser=await chromium.launch({headless:true,channel:'chromium',args:['--no-sandbox']});
  const page=await browser.newPage({viewport:{width:1280,height:800}});
  const errors=[];
  page.on('pageerror',e=>errors.push(e.message));
  await page.goto('http://127.0.0.1:8000/',{waitUntil:'networkidle'});
  await page.getByRole('button',{name:/Economy/}).click();
  await page.getByRole('button',{name:'Authorize'}).first().click();
  let saved=await page.evaluate(()=>JSON.parse(localStorage.getItem('statecraft-save')));
  if(saved.treasury<20 || !saved.log.some(x=>x.name==='Broaden the tax base')) throw new Error('Economy policy failed');
  await page.getByRole('button',{name:/Situation room/}).click();
  await page.locator('#addPriority').click();
  await page.locator('[data-priority="grid"]').click();
  saved=await page.evaluate(()=>JSON.parse(localStorage.getItem('statecraft-save')));
  if(saved.initiatives.length!==4 || saved.treasury>19.5) throw new Error('Priority was not charged and added');
  const before=saved.relations['United States'];
  await page.getByRole('button',{name:/Diplomacy/}).click();
  await page.locator('[data-country-action="United States"]').click();
  saved=await page.evaluate(()=>JSON.parse(localStorage.getItem('statecraft-save')));
  if(saved.relations['United States']!==before+6) throw new Error('Funded diplomacy did not improve relations');
  await page.locator('#advanceBtn').click();
  saved=await page.evaluate(()=>JSON.parse(localStorage.getItem('statecraft-save')));
  if(saved.month!==1 || saved.initiatives[3].progress<=0) throw new Error('Month advancement did not progress priorities');
  await page.reload({waitUntil:'networkidle'});
  const restored=await page.evaluate(()=>JSON.parse(localStorage.getItem('statecraft-save')));
  if(restored.month!==1 || restored.initiatives.length!==4) throw new Error('Save/load did not persist');
  await page.evaluate(()=>{const s=JSON.parse(localStorage.getItem('statecraft-save'));s.treasury=.1;localStorage.setItem('statecraft-save',JSON.stringify(s))});
  await page.reload({waitUntil:'networkidle'});
  await page.getByRole('button',{name:/Diplomacy/}).click();
  const relationBefore=await page.evaluate(()=>JSON.parse(localStorage.getItem('statecraft-save')).relations['China']);
  await page.locator('[data-country-action="China"]').click();
  const poor=await page.evaluate(()=>JSON.parse(localStorage.getItem('statecraft-save')));
  if(poor.relations.China!==relationBefore || poor.treasury!==.1) throw new Error('Unfunded diplomacy changed state');
  await page.evaluate(()=>{const s=JSON.parse(localStorage.getItem('statecraft-save'));s.treasury=18.6;s.initiatives=[{name:'a',area:'a',progress:0,icon:'+'},{name:'b',area:'b',progress:0,icon:'+'},{name:'c',area:'c',progress:0,icon:'+'},{name:'d',area:'d',progress:0,icon:'+'},{name:'e',area:'e',progress:0,icon:'+'}];localStorage.setItem('statecraft-save',JSON.stringify(s))});
  await page.reload({waitUntil:'networkidle'});
  await page.getByRole('button',{name:/Situation room/}).click();
  await page.locator('#addPriority').click();
  await page.locator('[data-priority="clinic"]').click();
  const capped=await page.evaluate(()=>JSON.parse(localStorage.getItem('statecraft-save')));
  if(capped.initiatives.length!==5 || capped.treasury!==18.6) throw new Error('Priority cap failed');
  await page.reload({waitUntil:'networkidle'});
  await page.screenshot({path:'/tmp/opencode/statecraft-final.jpg',type:'jpeg',quality:78});
  if(errors.length) throw new Error(`Browser errors: ${errors.join('; ')}`);
  console.log('PASS: navigation, policy spending/revenue, priority spending/cap, funded and unfunded diplomacy, monthly progression, save/load, zero page errors');
  await browser.close();
})().catch(e=>{console.error(e);process.exit(1)});

